    REFERENCES `patitasarriba`.`articulo` (`id_articulo`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION,
  CONSTRAINT `fk_articulo_categoria_categoria1`
    FOREIGN KEY (`id_categoria`)
    REFERENCES `patitasarriba`.`categoria` (`id_categoria`)
    ON DELETE NO ACTION
    ON UPDATE NO ACTION)
ENGINE = InnoDB;


