-- ============ procedures-articulo_categoria.sql ============
-- Procedimientos para patitasarriba.modelo.producto.Articulo (lista de categorias)
-- Tabla de enlace articulo_categoria: clave compuesta (id_articulo, id_categoria)

use patitasarriba;

DROP PROCEDURE IF EXISTS insertar_articulo_categoria;
DROP PROCEDURE IF EXISTS eliminar_articulo_categoria;
DROP PROCEDURE IF EXISTS eliminar_categorias_por_articulo;
DROP PROCEDURE IF EXISTS listar_categorias_por_articulo;
DROP PROCEDURE IF EXISTS listar_articulos_por_categoria;

DELIMITER //

-- Asocia un articulo con una categoria; si el enlace ya existia (inactivo), lo reactiva
CREATE PROCEDURE insertar_articulo_categoria (
    IN p_id_articulo INT,
    IN p_id_categoria INT
)
BEGIN
    INSERT INTO articulo_categoria (id_articulo, id_categoria, activo)
    VALUES (p_id_articulo, p_id_categoria, 1)
    ON DUPLICATE KEY UPDATE activo = 1;
END //

-- Borrado logico de una asociacion
CREATE PROCEDURE eliminar_articulo_categoria (
    IN p_id_articulo INT,
    IN p_id_categoria INT
)
BEGIN
    UPDATE articulo_categoria
    SET activo = 0
    WHERE id_articulo = p_id_articulo
      AND id_categoria = p_id_categoria;
END //

-- Borrado logico de todas las categorias de un articulo
CREATE PROCEDURE eliminar_categorias_por_articulo (IN p_id_articulo INT)
BEGIN
    UPDATE articulo_categoria
    SET activo = 0
    WHERE id_articulo = p_id_articulo;
END //

-- Categorias activas de un articulo (devuelve las columnas de categoria)
CREATE PROCEDURE listar_categorias_por_articulo (IN p_id_articulo INT)
BEGIN
    SELECT c.*
    FROM categoria c
    INNER JOIN articulo_categoria ac ON ac.id_categoria = c.id_categoria
    WHERE ac.id_articulo = p_id_articulo
      AND ac.activo = 1
      AND c.activo = 1;
END //

-- Articulos activos de una categoria (devuelve las columnas de articulo)
CREATE PROCEDURE listar_articulos_por_categoria (IN p_id_categoria INT)
BEGIN
    SELECT a.*
    FROM articulo a
    INNER JOIN articulo_categoria ac ON ac.id_articulo = a.id_articulo
    WHERE ac.id_categoria = p_id_categoria
      AND ac.activo = 1
      AND a.activo = 1;
END //

DELIMITER ;

-- ============ procedures-atencion.sql ============
-- Procedimientos CRUD para patitasarriba.modelo.atencion.Atencion
-- Los insumos y diagnosticos de la atencion se manejan en procedures-insumo_utilizado.sql
-- y procedures-atencion_diagnostico.sql

use patitasarriba;

DROP PROCEDURE IF EXISTS insertar_atencion;
DROP PROCEDURE IF EXISTS modificar_atencion;
DROP PROCEDURE IF EXISTS eliminar_atencion;
DROP PROCEDURE IF EXISTS buscar_atencion_por_id;
DROP PROCEDURE IF EXISTS buscar_atencion_por_detalle_cita;
DROP PROCEDURE IF EXISTS listar_atenciones;
DROP PROCEDURE IF EXISTS listar_atenciones_por_mascota;

DELIMITER //

-- Registra la ejecucion de un servicio de la cita (detalle_cita) y devuelve el id generado.
-- p_motivo_consulta puede ser NULL (servicios esteticos)
CREATE PROCEDURE insertar_atencion (
    IN p_id_detalle_cita INT,
    IN p_fecha_hora DATETIME,
    IN p_motivo_consulta VARCHAR(200),
    IN p_observaciones VARCHAR(500),
    IN p_activo TINYINT(1),
    OUT p_id INT
)
BEGIN
    INSERT INTO atencion (
        id_detalle_cita, fecha_hora, motivo_consulta, observaciones, activo
    )
    VALUES (
        p_id_detalle_cita, p_fecha_hora, p_motivo_consulta, p_observaciones, p_activo
    );

    SET p_id = LAST_INSERT_ID();
END //

-- Actualiza todos los campos de una atencion existente
CREATE PROCEDURE modificar_atencion (
    IN p_id INT,
    IN p_id_detalle_cita INT,
    IN p_fecha_hora DATETIME,
    IN p_motivo_consulta VARCHAR(200),
    IN p_observaciones VARCHAR(500),
    IN p_activo TINYINT(1)
)
BEGIN
    UPDATE atencion
    SET id_detalle_cita = p_id_detalle_cita,
        fecha_hora = p_fecha_hora,
        motivo_consulta = p_motivo_consulta,
        observaciones = p_observaciones,
        activo = p_activo
    WHERE id_atencion = p_id;
END //

-- Borrado logico: la atencion queda inactiva
-- (sus insumos y diagnosticos se desactivan antes, en la misma transaccion del BL)
CREATE PROCEDURE eliminar_atencion (IN p_id INT)
BEGIN
    UPDATE atencion
    SET activo = 0
    WHERE id_atencion = p_id;
END //

-- Solo devuelve la atencion si esta activa
CREATE PROCEDURE buscar_atencion_por_id (IN p_id INT)
BEGIN
    SELECT *
    FROM atencion
    WHERE id_atencion = p_id
      AND activo = 1;
END //

-- id_detalle_cita es UNIQUE: no filtra activo, para detectar tambien las atenciones inactivas
-- (validacion "un servicio se ejecuta en una sola atencion" en el BL) y para completar
-- DetalleCita.atencion
CREATE PROCEDURE buscar_atencion_por_detalle_cita (IN p_id_detalle_cita INT)
BEGIN
    SELECT *
    FROM atencion
    WHERE id_detalle_cita = p_id_detalle_cita;
END //

-- Solo lista las atenciones activas (respeta el borrado logico)
CREATE PROCEDURE listar_atenciones ()
BEGIN
    SELECT *
    FROM atencion
    WHERE activo = 1;
END //

-- Historial clinico: atenciones activas de una mascota (atencion -> detalle_cita -> cita -> mascota)
CREATE PROCEDURE listar_atenciones_por_mascota (IN p_id_mascota INT)
BEGIN
    SELECT a.*
    FROM atencion a
    INNER JOIN detalle_cita dc ON dc.id_detalle_cita = a.id_detalle_cita
    INNER JOIN cita c ON c.id_cita = dc.id_cita
    WHERE c.id_mascota = p_id_mascota
      AND a.activo = 1;
END //

DELIMITER ;

-- ============ procedures-atencion_diagnostico.sql ============
-- Procedimientos para patitasarriba.modelo.atencion.AtencionDiagnostico
-- Tabla de enlace atencion_diagnostico: clave compuesta (id_atencion, id_diagnostico),
-- con datos propios (nivel_gravedad, detalle_diagnostico)

use patitasarriba;

DROP PROCEDURE IF EXISTS insertar_atencion_diagnostico;
DROP PROCEDURE IF EXISTS modificar_atencion_diagnostico;
DROP PROCEDURE IF EXISTS eliminar_atencion_diagnostico;
DROP PROCEDURE IF EXISTS eliminar_diagnosticos_por_atencion;
DROP PROCEDURE IF EXISTS eliminar_atencion_diagnosticos_por_atencion_medica;
DROP PROCEDURE IF EXISTS buscar_atencion_diagnostico;
DROP PROCEDURE IF EXISTS listar_diagnosticos_por_atencion;
DROP PROCEDURE IF EXISTS listar_atencion_diagnosticos_por_atencion_medica;
DROP PROCEDURE IF EXISTS listar_atenciones_por_diagnostico;

DELIMITER //

-- Asigna un diagnostico a una atencion; si el enlace ya existia (inactivo), lo reactiva
-- con la gravedad y el detalle nuevos
CREATE PROCEDURE insertar_atencion_diagnostico (
    IN p_id_atencion INT,
    IN p_id_diagnostico INT,
    IN p_nivel_gravedad VARCHAR(10),
    IN p_detalle_diagnostico VARCHAR(200)
)
BEGIN
    INSERT INTO atencion_diagnostico (
        id_atencion, id_diagnostico, nivel_gravedad, detalle_diagnostico, activo
    )
    VALUES (
        p_id_atencion, p_id_diagnostico, p_nivel_gravedad, p_detalle_diagnostico, 1
    )
    ON DUPLICATE KEY UPDATE
        nivel_gravedad = p_nivel_gravedad,
        detalle_diagnostico = p_detalle_diagnostico,
        activo = 1;
END //

-- Actualiza la gravedad y el detalle de un diagnostico ya asignado a una atencion
CREATE PROCEDURE modificar_atencion_diagnostico (
    IN p_id_atencion INT,
    IN p_id_diagnostico INT,
    IN p_nivel_gravedad VARCHAR(10),
    IN p_detalle_diagnostico VARCHAR(200),
    IN p_activo TINYINT(1)
)
BEGIN
    UPDATE atencion_diagnostico
    SET nivel_gravedad = p_nivel_gravedad,
        detalle_diagnostico = p_detalle_diagnostico,
        activo = p_activo
    WHERE id_atencion = p_id_atencion
      AND id_diagnostico = p_id_diagnostico;
END //

-- Borrado logico de un diagnostico de una atencion
CREATE PROCEDURE eliminar_atencion_diagnostico (
    IN p_id_atencion INT,
    IN p_id_diagnostico INT
)
BEGIN
    UPDATE atencion_diagnostico
    SET activo = 0
    WHERE id_atencion = p_id_atencion
      AND id_diagnostico = p_id_diagnostico;
END //

-- Borrado logico de todos los diagnosticos de UNA atencion (paso previo a eliminar la atencion,
-- dentro de la misma transaccion)
CREATE PROCEDURE eliminar_diagnosticos_por_atencion (IN p_id_atencion INT)
BEGIN
    UPDATE atencion_diagnostico
    SET activo = 0
    WHERE id_atencion = p_id_atencion;
END //

-- Solo devuelve el enlace si esta activo
CREATE PROCEDURE buscar_atencion_diagnostico (
    IN p_id_atencion INT,
    IN p_id_diagnostico INT
)
BEGIN
    SELECT *
    FROM atencion_diagnostico
    WHERE id_atencion = p_id_atencion
      AND id_diagnostico = p_id_diagnostico
      AND activo = 1;
END //

-- Diagnosticos activos de UNA atencion (devuelve las filas del enlace, con gravedad y detalle)
CREATE PROCEDURE listar_diagnosticos_por_atencion (IN p_id_atencion INT)
BEGIN
    SELECT *
    FROM atencion_diagnostico
    WHERE id_atencion = p_id_atencion
      AND activo = 1;
END //

-- Enlaces activos de un diagnostico (util para la regla "no eliminar un diagnostico en uso")
CREATE PROCEDURE listar_atenciones_por_diagnostico (IN p_id_diagnostico INT)
BEGIN
    SELECT *
    FROM atencion_diagnostico
    WHERE id_diagnostico = p_id_diagnostico
      AND activo = 1;
END //

DELIMITER ;

-- ============ procedures-boleta.sql ============
-- Procedimientos CRUD para patitasarriba.modelo.boleta.Boleta
-- Las lineas de la boleta se manejan en procedures-detalle_boleta_serv.sql
-- y procedures-detalle_boleta_art.sql

use patitasarriba;

DROP PROCEDURE IF EXISTS insertar_boleta;
DROP PROCEDURE IF EXISTS modificar_boleta;
DROP PROCEDURE IF EXISTS eliminar_boleta;
DROP PROCEDURE IF EXISTS buscar_boleta_por_id;
DROP PROCEDURE IF EXISTS buscar_boleta_por_serie_correlativo;
DROP PROCEDURE IF EXISTS obtener_ultimo_correlativo;
DROP PROCEDURE IF EXISTS listar_boletas;
DROP PROCEDURE IF EXISTS listar_boletas_por_cliente;

DELIMITER //

-- Crea una boleta y devuelve el id generado
CREATE PROCEDURE insertar_boleta (
    IN p_id_cliente INT,
    IN p_serie_correlativo VARCHAR(15),
    IN p_fecha DATETIME,
    IN p_total DECIMAL(10,2),
    IN p_metodo_pago VARCHAR(20),
    IN p_activo TINYINT(1),
    OUT p_id INT
)
BEGIN
    INSERT INTO boleta (
        id_cliente, serie_correlativo, fecha, total, metodo_pago, activo
    )
    VALUES (
        p_id_cliente, p_serie_correlativo, p_fecha, p_total, p_metodo_pago, p_activo
    );

    SET p_id = LAST_INSERT_ID();
END //

-- Actualiza todos los campos de una boleta existente
CREATE PROCEDURE modificar_boleta (
    IN p_id_cliente INT,
    IN p_serie_correlativo VARCHAR(15),
    IN p_fecha DATETIME,
    IN p_total DECIMAL(10,2),
    IN p_metodo_pago VARCHAR(20),
    IN p_activo TINYINT(1),
    IN p_id INT
)
BEGIN
    UPDATE boleta
    SET id_cliente = p_id_cliente,
        serie_correlativo = p_serie_correlativo,
        fecha = p_fecha,
        total = p_total,
        metodo_pago = p_metodo_pago,
        activo = p_activo
    WHERE id_boleta = p_id;
END //

-- Anulacion (borrado logico): la boleta queda inactiva
-- (sus lineas se desactivan antes, en la misma transaccion del BL)
CREATE PROCEDURE eliminar_boleta (IN p_id INT)
BEGIN
    UPDATE boleta
    SET activo = 0
    WHERE id_boleta = p_id;
END //

-- Solo devuelve la boleta si esta activa
CREATE PROCEDURE buscar_boleta_por_id (IN p_id INT)
BEGIN
    SELECT *
    FROM boleta
    WHERE id_boleta = p_id
      AND activo = 1;
END //

-- serie_correlativo es UNIQUE: no filtra activo, para detectar tambien las boletas anuladas
CREATE PROCEDURE buscar_boleta_por_serie_correlativo (IN p_serie_correlativo VARCHAR(15))
BEGIN
    SELECT *
    FROM boleta
    WHERE serie_correlativo = p_serie_correlativo;
END //

-- Ultimo numero usado de una serie (p_serie = 'B001' -> serie_correlativo 'B001-000123' devuelve 123).
-- Devuelve 0 si la serie aun no tiene boletas. Incluye las anuladas: un correlativo no se reutiliza
CREATE PROCEDURE obtener_ultimo_correlativo (
    IN p_serie VARCHAR(4),
    OUT p_ultimo INT
)
BEGIN
    SELECT COALESCE(MAX(CAST(SUBSTRING(serie_correlativo, 6) AS UNSIGNED)), 0)
    INTO p_ultimo
    FROM boleta
    WHERE serie_correlativo LIKE CONCAT(p_serie, '-%');
END //

-- Solo lista las boletas activas (respeta el borrado logico)
CREATE PROCEDURE listar_boletas ()
BEGIN
    SELECT *
    FROM boleta
    WHERE activo = 1;
END //

-- Boletas activas de un cliente (util para la regla "no eliminar un cliente con boletas")
CREATE PROCEDURE listar_boletas_por_cliente (IN p_id_cliente INT)
BEGIN
    SELECT *
    FROM boleta
    WHERE id_cliente = p_id_cliente
      AND activo = 1;
END //

DELIMITER ;

