BEGIN
    SELECT *
    FROM detalle_boleta_art
    WHERE activo = 1;
END //

-- Lineas de articulo activas de UNA boleta (patron maestro-detalle)
CREATE PROCEDURE listar_detalles_boleta_art_por_boleta (IN p_id_boleta INT)
BEGIN
    SELECT *
